CREATE TABLE IF NOT EXISTS sessions (
 id TEXT PRIMARY KEY, module_id TEXT NOT NULL, module_version TEXT NOT NULL, investigator_id TEXT NOT NULL,
 experience_mode TEXT NOT NULL, status TEXT NOT NULL, session_version INTEGER NOT NULL DEFAULT 0,
 active_turn_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS session_snapshots (session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, session_version INTEGER NOT NULL, state_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS turns (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_index INTEGER NOT NULL, path_kind TEXT NOT NULL, status TEXT NOT NULL, player_input TEXT, narration_generation INTEGER NOT NULL DEFAULT 0, committed_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(session_id, turn_index));
CREATE TABLE IF NOT EXISTS game_events (event_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE, seq INTEGER NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, module_version TEXT NOT NULL, caused_by TEXT, created_at TEXT NOT NULL, UNIQUE(session_id, seq));
CREATE TABLE IF NOT EXISTS pending_interrupts (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE, status TEXT NOT NULL, check_payload_json TEXT NOT NULL, first_roll_json TEXT, push_description TEXT, push_consequence_json TEXT, resolution_json TEXT, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS idempotency_records (session_scope TEXT NOT NULL, command_type TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status_code INTEGER NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(session_scope, command_type, idempotency_key));
CREATE TABLE IF NOT EXISTS recovery_leases (turn_id TEXT PRIMARY KEY REFERENCES turns(id) ON DELETE CASCADE, lease_id TEXT NOT NULL, owner_id TEXT NOT NULL, generation_id INTEGER NOT NULL, expires_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transcript_entries (entry_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE, scene_id TEXT NOT NULL, speaker_entity_id TEXT, present_entity_ids_json TEXT NOT NULL, audible_entity_ids_json TEXT NOT NULL, visible_entity_ids_json TEXT NOT NULL, visibility_scope TEXT NOT NULL, claim_kind TEXT NOT NULL, referenced_event_ids_json TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ooc_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_acquisitions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, entity_id TEXT NOT NULL, fact_id TEXT NOT NULL, source_event_id TEXT NOT NULL, acquisition_method TEXT NOT NULL, acquired_at_seq INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS npc_beliefs (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, entity_id TEXT NOT NULL, source_transcript_id TEXT, claim_summary TEXT NOT NULL, belief_status TEXT NOT NULL, confidence REAL NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ui_directives (directive_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE, narration_generation INTEGER NOT NULL, source TEXT NOT NULL, directive_type TEXT NOT NULL, display_timing TEXT NOT NULL, payload_json TEXT NOT NULL, displayed_at TEXT, seq INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_notes (note_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, note_kind TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_call_audit (id TEXT PRIMARY KEY, session_id TEXT, turn_id TEXT, role TEXT NOT NULL, provider TEXT NOT NULL, model TEXT, proposal_raw_json TEXT, rejected_reason TEXT, latency_ms INTEGER, ttft_ms INTEGER, input_tokens INTEGER, output_tokens INTEGER, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_game_events_session_seq ON game_events(session_id, seq);
CREATE INDEX IF NOT EXISTS idx_turns_session_index ON turns(session_id, turn_index);
